import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=JSON.parse(JSON.stringify(v));function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('cliplaunch_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else if(['confirmation','stopConfirmation'].includes(k)&&typeof w==='string'&&w.length===43)x[k]='$'+k;else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}
const previewArgs={slotRef:'clip-slot:track-1:0',outputSafety:{safe:true,provenance:'operator observation'}};
const methods=['liveClipLaunchPreviewAsync','liveClipLaunchApplyAsync','liveClipLaunchStopAsync'];
const rows=[];for(const tool of methods){const valid=tool.includes('Preview')?previewArgs:tool.includes('Emergency')?{confirmation:'emergency-stop',expectedTargets:[],expectedRecording:'stopped'}:{transactionId:'missing',confirmation:'exact',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of Object.keys(valid)){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,0,'','x','a'.repeat(257),'a'.repeat(1025),{toString:null}])cases.push({...valid,[key]:value});}if(tool.includes('Preview'))for(const key of ['safe','provenance','observedAt','scope','extra'])for(const value of [null,false,true,0,'','unknown','simulator','operator',[],{}])cases.push({...valid,outputSafety:{...valid.outputSafety,[key]:value}});for(const args of cases){const host=new McpHost(new DeterministicLiveSimulator());let result;try{result=clean(await host[tool](1,args));}catch(e){result={error:e.message};}rows.push({tool,args,result});}}
const workflows=[];
const scenarios=['normal','expire','epoch','scene-edit','identity-edit','slot-edit','clip-edit','set-edit','armed','monitoring','quantization','playing','recording','empty-scene','missing-identity','apply-before','apply-ended','apply-after','apply-cancel','apply-refusal','apply-read','apply-current-read','apply-invalid-result','stop-before','stop-after','stop-refusal','stop-read','stop-current-read','stop-other-scene','stop-identity-edit','stop-recording','stop-armed','stop-already-stopped','apply-concurrent','stop-concurrent','apply-preabort','stop-preabort'];
for(const scenario of scenarios){
 const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();let fault='',fired=false,afterInvoke=false;
 if(scenario==='empty-scene')sim.state.tracks[0].clipSlots[0].clipRef=undefined;if(scenario==='missing-identity')delete sim.state.tracks[0].objectIdentity;
 function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null;}
 function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault.endsWith('-current-read'))){fired=true;throw Error('injected authoritative read failure');}}
 function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return cache.get(key);if(!fired&&['before','cancel','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error(fault.endsWith('cancel')?'operation cancelled before dispatch':'injected operation failure');}let result=sim.invoke(i);cache.set(key,result);afterInvoke=true;if(!fired&&fault==='apply-ended'){fired=true;sim.invoke({operation:'session.emergency-stop',args:{expectedTargets:[...new Set([...sim.state.playback.firedTargets,...sim.state.playback.playingTargets].map(t=>`${t.trackRef}|${t.clipSlotRef}|${t.sceneRef}`))],expectedRecording:'stopped'}});throw Error('injected operation failure');}if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure');}if(!fired&&fault==='apply-invalid-result'){fired=true;result={launched:'other',targets:[]};}if(!fired&&fault==='apply-external'){fired=true;sim.state.playback.playingTargets[0].sceneRef='scene:external';}return structuredClone(result);}
 const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async(c)=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
 const host=new McpHost(adapter),results=[],states=[];const preview=await host.liveClipLaunchPreviewAsync(1,previewArgs);results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text);const txid=body.transactionId;
 if(txid){const record=host.clipLaunchTransactions.get(txid);const controller=new AbortController();async function perform(action,key,aborted=false,concurrent=false){const args={transactionId:txid,confirmation:action==='apply'?body.confirmation:body.stopConfirmation,idempotencyKey:key};const id=results.length+1;const method=action==='apply'?'liveClipLaunchApplyAsync':'liveClipLaunchStopAsync';if(aborted)controller.abort();if(concurrent){const p=host[method](id,args);const other=host[method](id+1,{...args,idempotencyKey:'different'});const q=host[method](id+2,args);results.push(clean(await p),clean(await other),clean(await q));}else results.push(clean(await host[method](id,args,aborted?controller.signal:undefined)));states.push(clean(record));}
 if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='scene-edit')sim.state.scenes[0].name='Manual';if(scenario==='identity-edit')sim.state.scenes[0].objectIdentity='other';if(scenario==='slot-edit')sim.state.tracks[0].clipSlots[0].objectIdentity='other';if(scenario==='clip-edit')sim.state.tracks[0].clips[0].objectIdentity='other';if(scenario==='set-edit')sim.state.set.objectIdentity='other';if(scenario==='armed')sim.state.tracks[0].armed=true;if(scenario==='monitoring')sim.state.tracks[0].monitoringState='in';if(scenario==='quantization')sim.state.playback.transport.launchQuantization.normalized='none';if(scenario==='playing')sim.state.playback.transport.playing=true;if(scenario==='recording')sim.state.playback.transport.sessionRecord=true;if(scenario.startsWith('apply-'))fault=scenario;
 for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key,scenario==='apply-preabort',scenario==='apply-concurrent'&&key==='apply-key'&&results.length===1);fault='';fired=false;afterInvoke=false;
 if(scenario==='stop-other-scene')sim.state.playback.playingTargets[0].sceneRef='scene:external';if(scenario==='stop-identity-edit')sim.state.scenes[0].objectIdentity='other';if(scenario==='stop-recording')sim.state.playback.transport.sessionRecord=true;if(scenario==='stop-armed')sim.state.tracks[0].armed=true;if(scenario==='stop-already-stopped')sim.invoke({operation:'session.emergency-stop',args:{expectedTargets:[...new Set([...sim.state.playback.firedTargets,...sim.state.playback.playingTargets].map(t=>`${t.trackRef}|${t.clipSlotRef}|${t.sceneRef}`))],expectedRecording:'stopped'}});

 if(scenario.startsWith('stop-')&&!['stop-other-scene','stop-identity-edit','stop-recording','stop-armed','stop-already-stopped','stop-preabort','stop-concurrent'].includes(scenario))fault=scenario;
 for(const key of ['stop-key','other-stop-key','stop-key']){await perform('stop',key,scenario==='stop-preabort',scenario==='stop-concurrent'&&key==='stop-key'&&states.length===3);if(key==='stop-key')await perform('apply','apply-key');}fault='';fired=false;afterInvoke=false;await perform('stop','new-stop-key');await perform('apply','apply-key');}
 workflows.push({scenario,results,states,calls,state:sim.state});
}
fs.writeFileSync(new URL('host-clip-launch-oracle.json',import.meta.url),JSON.stringify({rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
